"""Заслон от имён переменных не латиницей в сценариях сборки.

Bash не принимает в именах переменных ничего, кроме латинских букв, цифр и
подчёркивания. Проверка синтаксиса это не ловит: `имя=значение` разбирается
как вызов команды `имя=значение`, а не как присваивание, — и падает только
при запуске, на машине сборки, через пять минут ожидания.

Я допустил эту ошибку дважды: 22 сентября в съёмке экранов и 23-го в
доставке, во второй раз уже после того, как объяснил её вслух. Значит,
помнить о ней нельзя — надо проверять.

Ничего, кроме самого Python, не требуется. Первая попытка разбирала файлы
через PyYAML, его на машине сборки не оказалось, и заслон уронил всю
проверку целиком — а сборка при этом ушла на телефон непроверенной.
Проверка не должна зависеть от того, что кто-то что-то доставит.

Тела вложенных документов (`<<'МЕТКА' … МЕТКА`) пропускаются: там обычно
лежит Python, а он кириллицу в именах принимает.
"""
import re
import sys
from pathlib import Path

КОРЕНЬ = Path(__file__).resolve().parents[1]
ПРИСВОЕНИЕ = re.compile(r"^[ \t]*([^\s=<>|&;()\"'`$#]+)=")
ИМЯ = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")
НАЧАЛО = re.compile(r"<<-?\s*'?\"?([A-Za-z_][A-Za-z0-9_]*)'?\"?")


def беда(текст: str):
    """Имена переменных, которые bash не примет."""
    метка = None
    for номер, строка in enumerate(текст.splitlines(), 1):
        if метка is not None:
            if строка.strip() == метка:
                метка = None
            continue
        голая = строка.lstrip()
        if голая.startswith("#"):
            continue
        if (m := НАЧАЛО.search(строка)):
            метка = m.group(1)
            continue
        if (m := ПРИСВОЕНИЕ.match(строка)) and not ИМЯ.match(m.group(1)):
            yield номер, m.group(1), голая.strip()


плохо = 0
файлы = sorted((КОРЕНЬ / ".github/workflows").glob("*.yml"))
if not файлы:
    print("::error::сценариев сборки не нашлось — проверять нечего")
    sys.exit(1)

for файл in файлы:
    for номер, переменная, строка in беда(файл.read_text(encoding="utf-8")):
        print(f"::error file={файл.relative_to(КОРЕНЬ)},line={номер}::"
              f"имя переменной «{переменная}» bash не примет — только "
              f"латиница, цифры и подчёркивание. {строка}")
        плохо += 1

if плохо:
    sys.exit(1)
print(f"Имена переменных в сценариях сборки в порядке ({len(файлы)} файла).")
